"""Validate YOLO labels generated by ``generate_yolo_dataset``."""

from __future__ import annotations

import argparse
from collections import Counter
import json
from pathlib import Path
from typing import Any

from PIL import Image


CLASS_NAMES = ("car", "box_obstacle", "cylinder_obstacle")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("dataset_dir", type=Path)
    return parser.parse_args()


def run(dataset_dir: Path) -> dict[str, Any]:
    if not dataset_dir.is_dir():
        raise FileNotFoundError(f"dataset directory does not exist: {dataset_dir}")
    errors: list[str] = []
    summary: dict[str, Any] = {"dataset_dir": str(dataset_dir), "splits": {}, "classes": list(CLASS_NAMES)}
    total_images = 0
    total_empty = 0
    total_instances = Counter()
    for split in ("train", "val", "test"):
        image_dir = dataset_dir / "images" / split
        label_dir = dataset_dir / "labels" / split
        split_images = sorted(image_dir.glob("*.png"))
        split_counts = Counter()
        empty = 0
        for image_path in split_images:
            label_path = label_dir / f"{image_path.stem}.txt"
            if not label_path.is_file():
                errors.append(f"missing label for {image_path}")
                continue
            try:
                with Image.open(image_path) as image:
                    width, height = image.size
                    if (width, height) != (256, 192):
                        errors.append(f"unexpected image size {image_path}: {(width, height)}")
            except OSError as error:
                errors.append(f"cannot open {image_path}: {error}")
                continue
            lines = [line.strip() for line in label_path.read_text(encoding="utf-8").splitlines() if line.strip()]
            if not lines:
                empty += 1
            for line_number, line in enumerate(lines, start=1):
                fields = line.split()
                if len(fields) != 5:
                    errors.append(f"{label_path}:{line_number}: expected 5 fields")
                    continue
                try:
                    class_id = int(fields[0])
                    values = [float(value) for value in fields[1:]]
                except ValueError:
                    errors.append(f"{label_path}:{line_number}: non-numeric label")
                    continue
                if class_id < 0 or class_id >= len(CLASS_NAMES):
                    errors.append(f"{label_path}:{line_number}: invalid class {class_id}")
                if any(value < 0.0 or value > 1.0 for value in values):
                    errors.append(f"{label_path}:{line_number}: normalized bbox out of range")
                if values[2] <= 0.0 or values[3] <= 0.0:
                    errors.append(f"{label_path}:{line_number}: non-positive bbox size")
                split_counts[class_id] += 1
        total_images += len(split_images)
        total_empty += empty
        total_instances.update(split_counts)
        summary["splits"][split] = {
            "images": len(split_images),
            "empty_label_images": empty,
            "instances": {CLASS_NAMES[key]: value for key, value in sorted(split_counts.items())},
        }
    summary["images"] = total_images
    summary["empty_label_images"] = total_empty
    summary["instances"] = {CLASS_NAMES[key]: value for key, value in sorted(total_instances.items())}
    summary["errors"] = errors
    summary["valid"] = not errors and total_images > 0
    (dataset_dir / "dataset_validation.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    return summary


def main() -> None:
    try:
        summary = run(parse_args().dataset_dir)
    except (FileNotFoundError, OSError, ValueError) as error:
        raise SystemExit(f"error: {error}") from error
    print(json.dumps(summary, indent=2))
    if not summary["valid"]:
        raise SystemExit(1)


if __name__ == "__main__":
    main()

